import React, { useState, useMemo, useEffect } from 'react';

// --- SVG Icon Components (as before) ---
const InfoIcon = () => <svg style={{ color: '#6b7280' }} xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>;
const AddIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>;
const EditIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>;
const DeleteIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>;
const SaveIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ marginRight: '8px' }}><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"></path><polyline points="17 21 17 13 7 13 7 21"></polyline><polyline points="7 3 7 8 15 8"></polyline></svg>;
const CheckIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#28a745' }}><polyline points="20 6 9 17 4 12"></polyline></svg>;
const XIcon = () => <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#dc3545' }}><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>;

export default function WDPerStudentPerActivityAllocationTab({ subject, sourceData }) {
    // --- Styles (as before) ---
    const styles = {
        panel: { backgroundColor: "#ffffff", borderRadius: "8px", boxShadow: "0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06)", padding: "32px", marginBottom: "32px" },
        h2: { fontSize: "20px", fontWeight: "600", color: "#111827", margin: 0 },
        headerContainer: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' },
        titleContainer: { display: 'flex', alignItems: 'center', gap: '12px' },
        addButton: { backgroundColor: "#111827", color: "white", padding: "8px 16px", borderRadius: "9999px", fontWeight: "600", border: "none", cursor: "pointer", display: 'flex', alignItems: 'center', gap: '8px' },
        tabContainer: { display: 'inline-flex', border: "1px solid #d1d5db", borderRadius: "9999px", marginBottom: "24px", overflow: 'hidden' },
        tab: { base: { padding: "10px 20px", fontSize: "14px", fontWeight: "600", cursor: "pointer", backgroundColor: "transparent", border: "none", borderRight: "1px solid #d1d5db" }, active: { backgroundColor: "#111827", color: "white" }, inactive: { color: "#374151" } },
        table: { base: { width: "100%", borderCollapse: "collapse" }, thead: { backgroundColor: "#f9fafb" }, th: { padding: "12px 16px", textAlign: "left", fontSize: "12px", fontWeight: "600", color: "#6b7280", textTransform: "uppercase", letterSpacing: "0.05em" }, tr: { borderBottom: "1px solid #e5e7eb" }, td: { padding: "8px 16px", fontSize: "14px", verticalAlign: "middle" } },
        inputField: { width: "95%", padding: "6px 8px", border: "1px solid #d1d5db", borderRadius: "6px", boxSizing: 'border-box' },
        actionIcons: { display: 'flex', alignItems: 'center', gap: '8px' },
        iconButton: { background: 'none', border: 'none', cursor: 'pointer', padding: '4px' },
        summaryRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: '24px', marginTop: '24px', borderTop: '1px solid #e5e7eb' },
        summaryLabel: { fontSize: '14px', color: '#374151' },
        summaryValue: { fontSize: '16px', fontWeight: 'bold', color: '#111827' },
        footer: { display: 'flex', justifyContent: 'flex-start', marginTop: '32px' },
        saveButton: { backgroundColor: "#111827", color: "white", padding: "10px 24px", borderRadius: "6px", fontWeight: "600", border: "none", cursor: "pointer", display: 'flex', alignItems: 'center' }
    };

    // --- Dynamic Calculation Logic ---
    const calculateAllocation = (staffMember, roleName, source) => {
        if (!staffMember || !roleName || !source?.perStudentAllocations || !source?.activityAllocations) {
            return 0;
        }

        const { students, groups } = staffMember;
        const termMultiplier = subject?.term === 'Autumn' ? 1.0 : 0.923; // Assuming C12/G12 is term multiplier

        // Find the matching role data from the PerStudentAllocationTab
        const perStudentRoleData = source.perStudentAllocations.find(p => p.role === roleName);
        const perStudentFactor = perStudentRoleData ? (perStudentRoleData.marking + perStudentRoleData.consultation + perStudentRoleData.coordination) : 0;
        const perStudentPart = (students / 25) * perStudentFactor;

        // Calculate parts for each activity
        let activitiesPart = 0;
        source.activityAllocations.forEach((activity, index) => {
            const activityId = `activity-${index + 1}`; // Assuming activity IDs are activity-1, activity-2 etc.
            const numGroupsForStaff = groups[activityId] || 0;
            const weeklyClassTime = activity.weeklyClassTime || 0;

            // Find the distribution for the current role in the activity data
            const activityRoleDist = activity.distribution?.[roleName] || {};
            const allocationWeight = (activityRoleDist['Preparation / Setup'] || 0) + (activityRoleDist['Delivery / Supervision'] || 0);

            // Per Excel formula: B67*F66*$C$12*0.0125 seems to be the base activity allocation
            // The 0.0125 seems to be a base rate which is then distributed by the allocationWeight
            const activityPart = numGroupsForStaff * weeklyClassTime * termMultiplier * 0.0125 * allocationWeight;
            activitiesPart += activityPart;
        });

        // The formula structure in Excel seems complex. Let's use a simplified and common structure:
        // Per-student part + Sum of activity parts.
        return perStudentPart + activitiesPart;
    };

    const coordinatorAllocation = useMemo(() => {
        if (!sourceData) return 0;

        const totalStudents = sourceData.totalStudents || 0;
        const termMultiplier = subject?.term === 'Autumn' ? 1.0 : 0.923;

        // Part 1: Per-student allocation for the coordinator
        const coordPerStudentData = sourceData.perStudentAllocations?.find(p => p.id === 'coord');
        const perStudentFactor = coordPerStudentData ? (coordPerStudentData.marking + coordPerStudentData.consultation + coordPerStudentData.coordination) : 0;
        const perStudentPart = (totalStudents / 25) * perStudentFactor;

        // Part 2: Activity allocations for the coordinator
        let activitiesPart = 0;
        sourceData.activityAllocations?.forEach(activity => {
            const numGroups = activity.numberOfGroups || 0;
            const weeklyClassTime = activity.weeklyClassTime || 0;
            const coordDist = activity.distribution?.['Subject Coordinator'] || {};
            const allocationWeight = (coordDist['Preparation / Setup'] || 0) + (coordDist['Delivery / Supervision'] || 0);

            // Replicating the logic from staff calculation for the coordinator
            activitiesPart += numGroups * weeklyClassTime * termMultiplier * 0.0125 * allocationWeight;
        });

        return perStudentPart + activitiesPart;

    }, [sourceData, subject]);

 // --- State Management ---
    const [rolesData, setRolesData] = useState([
        { id: "role-a", name: "Lecturer", activities: [{ id: "activity-1", name: "Activity 1 - Lecture" }, { id: "activity-2", name: "Activity 2 - Tutorial" }, { id: "activity-3", name: "Activity 3 - Workshop" }], staffAllocations: [{ id: "staff-1", name: "Tom", students: 30, groups: { "activity-1": 2, "activity-2": 0, "activity-3": 0 } }, { id: "staff-2", name: "Usha", students: 30, groups: { "activity-1": 2, "activity-2": 0, "activity-3": 0 } }, { id: "staff-3", name: "Victoria", students: 40, groups: { "activity-1": 0, "activity-2": 3, "activity-3": 0 } }] },
        { id: "role-b", name: "Exam marker", activities: [{ id: "activity-1", name: "Marking" }], staffAllocations: [] },
        { id: "role-c", name: "Tutor", activities: [{ id: "activity-1", name: "Tutorial" }], staffAllocations: [] },
        { id: "role-d", name: "Lab supervisor", activities: [{ id: "activity-1", name: "Lab Session" }], staffAllocations: [] }
    ]);
    const [activeTab, setActiveTab] = useState('role-a');
    const [editingId, setEditingId] = useState(null);
    const [backupRow, setBackupRow] = useState(null);
    const [errors, setErrors] = useState({});

    // --- Validation Logic ---
    useEffect(() => {
        const newErrors = {};
        if (sourceOfTruthData?.totalStudents > 0) {
            const currentTotalStudents = rolesData.reduce((total, role) => total + role.staffAllocations.reduce((subTotal, staff) => subTotal + (staff.students || 0), 0), 0);
            if (currentTotalStudents > sourceOfTruthData.totalStudents) {
                newErrors.students = `Error: Allocated students (${currentTotalStudents}) exceeds subject total of ${sourceOfTruthData.totalStudents}.`;
            }
        }
        const groupErrors = {};
        rolesData.forEach(role => {
            role.activities.forEach((activity, index) => {
                const sourceActivity = sourceOfTruthData?.activityGroups[index];
                if (sourceActivity) {
                    const allocatedGroups = role.staffAllocations.reduce((sum, staff) => sum + (staff.groups[activity.id] || 0), 0);
                    if (allocatedGroups > sourceActivity.numberOfGroups) {
                        groupErrors[activity.id] = `For "${sourceActivity.name}", allocated groups (${allocatedGroups}) exceed total of ${sourceActivity.numberOfGroups}.`;
                    }
                }
            });
        });
        if (Object.keys(groupErrors).length > 0) newErrors.groups = groupErrors;
        setErrors(newErrors);
    }, [rolesData, sourceOfTruthData]);

    const activeRole = useMemo(() => rolesData.find(role => role.id === activeTab), [rolesData, activeTab]);

    // --- Event Handlers ---
    const handleEdit = (staff) => {
        setBackupRow(staff);
        setEditingId(staff.id);
    };

    const handleCancel = () => {
        setRolesData(currentData => currentData.map(role => {
            if (role.id === activeTab) {
                return { ...role, staffAllocations: role.staffAllocations.map(staff => staff.id === editingId ? backupRow : staff) };
            }
            return role;
        }));
        setEditingId(null);
        setBackupRow(null);
    };

    const handleSaveRow = () => {
        setEditingId(null);
        setBackupRow(null);
    };

    const handleInputChange = (staffId, field, value, activityId = null) => {
        const numericValue = value === '' ? 0 : Math.max(0, parseInt(value, 10));
        setRolesData(currentRoles => currentRoles.map(role => {
            if (role.id === activeTab) {
                const updatedAllocations = role.staffAllocations.map(staff => {
                    if (staff.id === staffId) {
                        if (field === 'groups' && activityId) {
                            return { ...staff, groups: { ...staff.groups, [activityId]: numericValue } };
                        }
                        return { ...staff, [field]: field === 'name' ? value : numericValue };
                    }
                    return staff;
                });
                return { ...role, staffAllocations: updatedAllocations };
            }
            return role;
        }));
    };

    const handleAddRow = () => {
        const newStaff = { id: `staff-${Date.now()}`, name: '', students: 0, groups: activeRole.activities.reduce((acc, activity) => ({ ...acc, [activity.id]: 0 }), {}) };
        setRolesData(currentRoles => currentRoles.map(role => role.id === activeTab ? { ...role, staffAllocations: [...role.staffAllocations, newStaff] } : role));
        handleEdit(newStaff); // Enter edit mode for the new row immediately
    };

    const handleDeleteRow = (staffId) => {
        if (window.confirm("Are you sure you want to delete this row?")) {
            setRolesData(currentRoles => currentRoles.map(role => role.id === activeTab ? { ...role, staffAllocations: role.staffAllocations.filter(s => s.id !== staffId) } : role));
        }
    };

    return (
        <div style={styles.panel}>
            {errors.students && <div style={{color: '#dc3545', backgroundColor: '#f8d7da', border: '1px solid #f5c6cb', padding: '1rem', borderRadius: '6px', marginBottom: '1rem', textAlign: 'center'}}>{errors.students}</div>}
            {errors.groups && Object.values(errors.groups).map(msg => <div key={msg} style={{color: '#dc3545', backgroundColor: '#f8d7da', border: '1px solid #f5c6cb', padding: '1rem', borderRadius: '6px', marginBottom: '1rem', textAlign: 'center'}}>{msg}</div>)}

            <div style={styles.headerContainer}>
                <div style={styles.titleContainer}>
                    <h2 style={styles.h2}>Per-student / Per-activity Allocation</h2>
                    <InfoIcon />
                </div>
                <button style={styles.addButton} onClick={handleAddRow}>
                    <AddIcon /> Add
                </button>
            </div>

            <div style={styles.tabContainer}>
                {rolesData.map((role, index) => (
                    <button key={role.id} onClick={() => setActiveTab(role.id)} style={{ ...styles.tab.base, ...(activeTab === role.id ? styles.tab.active : styles.tab.inactive), ...(index === rolesData.length - 1 && { borderRight: 'none' }) }}>
                        {`Role ${role.id.split('-')[1].toUpperCase()} ${role.name}`}
                    </button>
                ))}
            </div>

            <table style={styles.table.base}>
                <thead>
                    <tr>
                        <th style={styles.table.th}>Actions</th>
                        <th style={styles.table.th}>Staff Member Acting in Role</th>
                        <th style={styles.table.th}>Number of Students</th>
                        {activeRole?.activities.map(activity => <th key={activity.id} style={styles.table.th}>{`Number of groups for ${activity.name.replace('Activity 1 - ', '')}`}</th>)}
                        <th style={{...styles.table.th, textAlign: 'right'}}>Allocation</th>
                    </tr>
                </thead>
                <tbody>
                    {activeRole?.staffAllocations.map(staff => {
                        const isEditing = editingId === staff.id;
                        return (
                            <tr key={staff.id}>
                                <td style={styles.table.td}>
                                    <div style={styles.actionIcons}>
                                        {isEditing ? (
                                            <>
                                                <button style={styles.iconButton} onClick={handleSaveRow} title="Save"><CheckIcon /></button>
                                                <button style={styles.iconButton} onClick={handleCancel} title="Cancel"><XIcon /></button>
                                            </>
                                        ) : (
                                            <>
                                                <button style={styles.iconButton} onClick={() => handleEdit(staff)} title="Edit"><EditIcon /></button>
                                                <button style={styles.iconButton} onClick={() => handleDeleteRow(staff.id)} title="Delete"><DeleteIcon /></button>
                                            </>
                                        )}
                                    </div>
                                </td>
                                <td style={styles.table.td}>
                                    {isEditing ? <input type="text" style={styles.inputField} value={staff.name} onChange={(e) => handleInputChange(staff.id, 'name', e.target.value)} /> : staff.name}
                                </td>
                                <td style={styles.table.td}>
                                    {isEditing ? <input type="number" min="0" style={styles.inputField} value={staff.students} onChange={(e) => handleInputChange(staff.id, 'students', e.target.value)} /> : staff.students}
                                </td>
                                {activeRole.activities.map(activity => (
                                    <td key={activity.id} style={styles.table.td}>
                                        {isEditing ? <input type="number" min="0" style={styles.inputField} value={staff.groups[activity.id] || 0} onChange={(e) => handleInputChange(staff.id, 'groups', e.target.value, activity.id)} /> : (staff.groups[activity.id] || 0)}
                                    </td>
                                ))}
                                {/* <td style={{ ...styles.table.td, textAlign: 'right', fontWeight: 'bold' }}>
                                    {(calculateStaffAllocation(staff) * 100).toFixed(1)}%
                                </td> */}
                                {/* THIS IS THE KEY CHANGE */}
                                <td style={{ ...styles.table.td, textAlign: 'right', fontWeight: 'bold' }}>
                                    {(calculateAllocation(staff, activeRole.name, sourceData) * 100).toFixed(1)}%
                                </td>
                            </tr>
                        );
                    })}
                </tbody>
            </table>

            <div style={styles.summaryRow}>
                <span style={styles.summaryLabel}>Allocation to Subject Coordinator: {subject?.subjectCoordinator || "Tom"}</span>
                {/* THIS IS THE KEY CHANGE */}
                <span style={styles.summaryValue}>{(coordinatorAllocation * 100).toFixed(1)}%</span>
            </div>

            <div style={styles.footer}>
                <button style={styles.saveButton}>
                    <SaveIcon />
                    Save
                </button>
            </div>
        </div>
    );
}
